#[allow(dead_code)]#[path="../cyclotomic-lp/ring.rs"]mod ring;
#[allow(dead_code)]#[path="../affine-lp/dsu.rs"]mod affine;
#[path="../setup/fast.rs"]mod eager;
#[path="../root-action/prepare.rs"]mod geometry;
#[path="../multi/algebra.rs"]mod algebra;
#[path="../normalized/source.rs"]mod source;
use hec_native_ic::{counted,fp::Fp,jac::{Curve,Div},poly::Poly,rng::Rng,oracle::{split_reference,OracleStats}};
use ring::{R,ZERO,ONE,Ring};
use std::{collections::BTreeMap,fs};
struct Input{a:u64,support:Vec<(usize,u64,u64)>}
fn rw(c:&Curve,g:&[(usize,usize,u64)],j:usize,y:u64,r:&Ring)->R{let v=r.z(g[j].1);if y==g[j].2{v}else{assert_eq!(y,c.fp.neg(g[j].2));r.neg(v)}}
fn run(c:&Curve,d:&Div,target:&Div,ell:u64,input:&[Input],arm:u64)->(u64,u64,usize,u64){let(fb,z,lambda)=if arm==0{let(fb,z,a)=eager::prepare(c);let(_,_,deg,l)=algebra::certificate(&a,ell);assert_eq!(deg,1);(fb,z,l)}else{let(fb,z)=geometry::prepare(c);(fb,z,None)};let mut geo=vec![(usize::MAX,0,0);fb.len()];let mut cols=0;for j in 0..fb.len(){if geo[j].0!=usize::MAX{continue}let(mut x,y)=(fb[j].0,fb[j].1);for e in 0..5{let idx=fb.binary_search_by_key(&x,|p|p.0).unwrap();assert_eq!(geo[idx].0,usize::MAX);geo[idx]=(cols,e,y);x=c.fp.mul(x,z);}cols+=1;}let perm=|r:usize|if r==0{cols-1}else{r-1};
if let Some(lambda)=lambda{let f=Fp::new(ell);let mut powers=[1;5];for j in 1..5{powers[j]=f.mul(powers[j-1],lambda)}let map:Vec<_>=geo.iter().enumerate().map(|(j,&(r,e,y))|(perm(r),if fb[j].1==y{powers[e]}else{assert_eq!(fb[j].1,c.fp.neg(y));f.neg(powers[e])})).collect();let mut s=affine::Affine::new(cols-1,ell);if let Some((_,v))=source::equation(c,d,&fb,&map,cols,ell){let mut v=v;v.push(0);s.insert(&v,1);}for(index,row)in input.iter().enumerate(){let mut v=vec![0;cols+1];for &(_,x,y)in &row.support{let j=fb.binary_search_by_key(&x,|p|p.0).unwrap();let a=if y==fb[j].1{map[j].1}else{assert_eq!(y,c.fp.neg(fb[j].1));f.neg(map[j].1)};v[map[j].0]=f.add(v[map[j].0],a);}v[cols]=1;s.insert(&v,f.neg(row.a));if let Some(k)=s.k(){assert_eq!(c.mul(d,k),*target);return(lambda,k,index+1,row.a)}}}else{let mut s=ring::Dsu::new(cols-1,ell);let r=Ring::new(ell);if let Some(roots)=split_reference(&d.u,&c.fp,&mut OracleStats::default()){let mut v=vec![ZERO;cols+1];let mut sum=c.zero();for &(x,m)in roots.as_slice(){let j=fb.binary_search_by_key(&x,|p|p.0).unwrap();let y=d.v.eval(x,&c.fp);let idx=perm(geo[j].0);v[idx]=r.add(v[idx],r.scale(rw(c,&geo,j,y,&r),m as u64));for _ in 0..m{sum=c.add_place(&sum,x,y);}}assert_eq!(sum,*d);s.insert(&v,ONE);}
for(index,row)in input.iter().enumerate(){let mut v=vec![ZERO;cols+1];for &(orbit,x,y)in &row.support{let j=fb.binary_search_by_key(&x,|p|p.0).unwrap();assert_eq!(geo[j].0,orbit);let idx=perm(orbit);v[idx]=r.add(v[idx],rw(c,&geo,j,y,&r));}v[cols]=ONE;s.insert(&v,r.constant((ell-row.a%ell)%ell));if let Some((lambda,Some(k)))=s.unique(){assert_eq!(c.mul(d,k),*target);return(lambda,k,index+1,row.a)}}}panic!("retained stream incomplete")}
fn main(){counted::disable();let mut data=BTreeMap::<(u64,u64),Vec<Input>>::new();for l in fs::read_to_string("research/hec_residual_span_20261116/incidence-oracle/ROOTS.tsv").unwrap().lines().skip(1){let v:Vec<_>=l.split('\t').collect();let n=|j:usize|v[j].parse::<u64>().unwrap();let support:Vec<_>=v[5].split(',').map(|s|{let x:Vec<u64>=s.split(':').map(|x|x.parse().unwrap()).collect();(x[0]as usize,x[1],x[2])}).collect();if support.iter().any(|x|x.0==0){data.entry((n(0),n(1))).or_default().push(Input{a:n(3),support});}}
println!("p\tsm\trep\tarm\tmodulus\tlambda\tk\trows\tanchor\tcounts");let mut calls=0;for(p,cc,ell)in[(101,2,7481),(251,18,67931),(601,7,411491)]{let c=Curve::new(Fp::new(p),Poly::from_coeffs(&[cc,0,0,0,0,1]));let(fb,z)=geometry::prepare(&c);let base=c.place(fb[0].0,fb[0].1);let mut rng=Rng::new(2026112500^p);for sm in [1,17]{let d=c.mul(&base,sm);let qualification=1+rng.below(ell-1);let target=c.mul(&d,qualification);let mut prior=BTreeMap::new();let mut paired=None;for rep in 0..2{for i in 0..2{let arm=if rep==0{i}else{1-i};counted::reset();let out=run(&c,&d,&target,ell,&data[&(p,sm)],arm);let counts=counted::snapshot();counted::disable();assert_eq!(c.mul(&d,out.0),algebra::action(&c,&d,z));assert_eq!(c.mul(&d,out.1),target);assert_eq!(out.1,qualification);if let Some(pair)=paired{assert_eq!(pair,(out.0,out.1))}else{paired=Some((out.0,out.1));}let sig=(out,counts.clone());if rep==1{assert_eq!(prior[&arm],sig)}else{prior.insert(arm,sig);}for(modulus,v)in counts{assert_eq!(v[8],2*v[7]+v[5]+v[6]);println!("{p}\t{sm}\t{rep}\t{arm}\t{modulus}\t{}\t{}\t{}\t{}\t{}",out.0,out.1,out.2,out.3,v.iter().map(u64::to_string).collect::<Vec<_>>().join(","));}calls+=1;}}}}assert_eq!(calls,24);eprintln!("calls={calls} same_action_and_target=true exact_repeats=true preparation_source_normalization_row_assembly_elimination_final_scalar_charged=true relation_producer_excluded=true no_full_cost_claim=true");}
